CREATE TABLE ezkeyword_attribute_link (id INT AUTO_INCREMENT NOT NULL, keyword_id INT DEFAULT 0 NOT NULL, objectattribute_id INT DEFAULT 0 NOT NULL, version INT DEFAULT 0 NOT NULL, INDEX ezkeyword_attr_link_oaid (objectattribute_id), INDEX ezkeyword_attr_link_kid_oaid (keyword_id, objectattribute_id), INDEX ezkeyword_attr_link_oaid_ver (objectattribute_id, version), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
